<?php namespace Workspace; ?>
<section class="panel"><h2>Политики хранения и выдача</h2><p>Сроки задаются владельцем после юридической проверки. Без назначенной политики очистка запрещена. Удержание распространяется на все версии и подписанные оригиналы. Связанные договоры, акты и клиентские PDF не очищаются.</p></section>
<?php if($owner): ?><details class="editor"><summary>Новая политика хранения</summary><form method="post" class="formgrid"><?php formFields('retention.policy') ?><label>Страна (ISO alpha-2)<input name="country" maxlength="2" required placeholder="GB"></label><label>Тип<select name="kind"><?php foreach(DOC_KINDS as $k=>$name): ?><option value="<?= h($k) ?>"><?= h($name) ?></option><?php endforeach ?></select></label><label>Срок в днях<input name="days" type="number" min="1" max="36525" required></label><label>Правовое или договорное основание<input name="basis" maxlength="1000" required></label><div class="formend"><button class="primary">Создать политику</button></div></form></details>
<section class="panel"><h2>Политики организации</h2><?php foreach($policies as $p): ?><p>#<?= (int)$p['id'] ?> · <?= h($p['country']) ?> · <?= h(DOC_KINDS[$p['kind']]) ?> · <?= (int)$p['days'] ?> дн. · <?= h($p['basis']) ?></p><?php endforeach ?></section><?php endif ?>
<section class="panel"><h2>Документы</h2><?php foreach(array_slice($docs,0,50) as $d): ?><p><a href="<?= h(url('retention',['id'=>$d['id'],'v'=>$d['revision']])) ?>"><?= h($d['title']) ?></a> · <?= h($d['project_title']) ?> · <?= h(DOC_KINDS[$d['kind']]) ?></p><?php endforeach ?><?php if(count($docs)>50): ?><a href="<?= h(url('retention',['before'=>$docs[49]['id']])) ?>">Следующая страница</a><?php endif ?></section>
<?php if($selected): $d=$selected; $doc=(int)$d['id'];$rev=(int)$d['revision']; $fields=function(string $action,?int $package=null)use($doc,$rev){formFields($action);echo '<input type="hidden" name="document_id" value="'.$doc.'"><input type="hidden" name="revision" value="'.$rev.'">';if($package!==null)echo '<input type="hidden" name="package_id" value="'.$package.'">';}; ?>
<section class="panel"><h2>Документ #<?= $doc ?> · редакция <?= $rev ?></h2><p><a href="<?= h(url('document',['id'=>$doc])) ?>">История документа</a> · <?= h($d['storage_state']) ?> · SHA-256 <code><?= h($d['sha256']) ?></code></p><?php foreach($versions as $v): ?><p><a href="<?= h(url('retention',['id'=>$doc,'v'=>$v['revision']])) ?>">v<?= (int)$v['revision'] ?></a> · <?= h($v['storage_state']) ?> · <?= (int)$v['size'] ?> байт</p><?php endforeach ?>
<p>Политика: <?= $policy?h($policy['country'].' · '.$policy['days'].' дн. · '.$policy['basis']):'Не назначена; очистка запрещена' ?>.</p><?php if($policy): ?><p>Самая ранняя дата удаления этой редакции (UTC): <?= h(gmdate('Y-m-d H:i:s',max(strtotime($d['created_at'].' UTC'),strtotime($policy['starts_on'].' UTC'))+(int)$policy['days']*86400)) ?>; с учётом удержаний и связей.</p><?php endif ?>
<?php if($owner): ?><form method="post" class="formgrid"><?php $fields('retention.assign') ?><label>Назначить/увеличить срок<select name="policy_id" required><?php foreach($policies as $p): if($p['kind']!==$d['kind'])continue; ?><option value="<?= (int)$p['id'] ?>">#<?= (int)$p['id'] ?> · <?= h($p['country']) ?> · <?= (int)$p['days'] ?> дн.</option><?php endforeach ?></select></label><label>Дата начала срока (UTC)<input type="date" name="starts_on" value="<?= h($policy['starts_on']??gmdate('Y-m-d')) ?>" required></label><button>Назначить</button></form><?php endif ?>
</section>
<section class="panel"><h2>Legal Hold</h2><?php foreach($holds as $hold): ?><p>#<?= (int)$hold['id'] ?> · <?= $hold['released_at']===null?'Действует':'Снято' ?> · <?= h($hold['reason']) ?> · <?= h(gmdate('c',(int)$hold['created_at'])) ?></p><?php if($hold['released_at']!==null): ?><p>Основание снятия: <?= h($hold['release_reason']) ?></p><?php elseif($owner): ?><form method="post" class="formgrid"><?php $fields('retention.release') ?><input type="hidden" name="hold_id" value="<?= (int)$hold['id'] ?>"><label>Основание снятия<input name="reason" maxlength="1000" required></label><button>Снять удержание</button></form><?php endif ?><?php endforeach ?>
<?php if($owner): ?><form method="post" class="formgrid"><?php $fields('retention.hold') ?><label>Спор / основание удержания<input name="reason" maxlength="1000" required></label><button>Установить удержание</button></form><?php endif ?></section>
<section class="panel"><h2>Хранилище</h2><p>PDF: <?= h($d['storage_state']) ?></p><?php if($owner&&$d['storage_state']!=='purged'): ?><form method="post"><?php $fields($d['storage_state']==='object'?'retention.restore':'retention.offload') ?><button><?= $d['storage_state']==='object'?'Восстановить в БД':'Перенести в объекты' ?></button></form><?php endif ?>
<?php foreach($signed as $s): ?><p>Подписанный оригинал #<?= (int)$s['id'] ?> · <?= (int)$s['test_mode']?'TEST':'LIVE' ?> · <?= h($s['storage_state']) ?> · <?= (int)$s['pdf_size'] ?> байт</p><?php if($owner): ?><form method="post"><?php $fields($s['storage_state']==='object'?'retention.restore':'retention.offload',(int)$s['id']) ?><button><?= $s['storage_state']==='object'?'Восстановить оригинал в БД':'Перенести оригинал в объекты' ?></button></form><?php endif ?><?php endforeach ?>
<?php if($owner&&($eligible||($d['storage_state']==='purged'&&$d['object_key']!==null))): ?><form method="post" class="formgrid"><?php $fields('retention.purge') ?><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю удаление содержимого по политике (необратимо, кроме резервных копий)</label><button>Очистить</button></form><?php else: ?><p>Очистка недоступна: срок, удержание, связанные записи либо файл уже удалён.</p><?php endif ?></section>
<?php if($owner): ?><section class="panel"><h2>Временные ссылки</h2><?php if($linkToken!==null): ?><p>Скопируйте ссылку сейчас; токен больше не отображается. Любой обладатель ссылки сможет скачать PDF в пределах срока и лимита.</p><a rel="noreferrer" href="<?= h(url('retention.share',['token'=>$linkToken])) ?>">Ссылка для получателя (копировать адрес)</a><?php endif ?>
<?php if($d['storage_state']!=='purged'): ?><form method="post" class="formgrid"><?php $fields('retention.link') ?><label>Файл<select name="package_id"><option value="">Исходная редакция PDF</option><?php foreach($signed as $s): ?><option value="<?= (int)$s['id'] ?>">Подписанный оригинал #<?= (int)$s['id'] ?> (<?= (int)$s['test_mode']?'TEST':'LIVE' ?>)</option><?php endforeach ?></select></label><label>Срок в минутах<input type="number" min="1" max="10080" name="minutes" value="60" required></label><label>Число выдач<input type="number" min="1" max="20" name="uses" value="1" required></label><button>Создать ссылку</button></form><?php endif ?>
<?php foreach($links as $l): ?><p>#<?= (int)$l['id'] ?> · до <?= h(gmdate('c',(int)$l['expires_at'])) ?> · <?= (int)$l['uses'] ?>/<?= (int)$l['max_uses'] ?> · <?= $l['revoked_at']!==null?'Отозвана':((int)$l['expires_at']<=time()?'Истекла':((int)$l['uses']>=(int)$l['max_uses']?'Лимит исчерпан':'Действует')) ?> <?= $l['package_id']?' · оригинал #'.(int)$l['package_id']:'' ?></p><?php if($l['revoked_at']===null): ?><form method="post"><?php $fields('retention.revoke') ?><input type="hidden" name="link_id" value="<?= (int)$l['id'] ?>"><button>Отозвать</button></form><?php endif ?><?php endforeach ?></section><?php endif ?>
<section class="panel"><h2>Журнал выдачи этой редакции</h2><?php foreach(array_slice($deliveries,0,100) as $e): ?><p>#<?= (int)$e['id'] ?> · <?= h(gmdate('c',(int)$e['issued_at'])) ?> · <?= h($e['channel']) ?> · <?= $e['actor_id']?'user #'.(int)$e['actor_id']:($e['guest_id']?'guest #'.(int)$e['guest_id']:'link #'.(int)$e['link_id']) ?> · <?= (int)$e['bytes_size'] ?> байт · <code><?= h($e['payload_sha256']) ?></code></p><?php endforeach ?><?php if(count($deliveries)>100): ?><a href="<?= h(url('retention',['id'=>$doc,'v'=>$rev,'log_before'=>$deliveries[99]['id']])) ?>">Предыдущие выдачи</a><?php endif ?></section>
<?php endif ?>
